import React, { useState, useEffect, useContext } from 'react';
import { AuthContext } from '../context/AuthContext';
import API from '../utils/api';
import { FiClock, FiDollarSign, FiBookmark, FiSearch } from 'react-icons/fi';
import { Link } from 'react-router-dom';
import ApplyModal from '../components/projects/ApplyModal';

const Browse = () => {
  const [projects, setProjects] = useState([]);
  const [filteredProjects, setFilteredProjects] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchText, setSearchText] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('All Categories');
  const [budgetFilter, setBudgetFilter] = useState('All Budgets');
  const [levelFilter, setLevelFilter] = useState('All Levels');
  const [selectedProject, setSelectedProject] = useState(null);
  const [appliedProjects, setAppliedProjects] = useState([]);
  const { user } = useContext(AuthContext);

  useEffect(() => {
    fetchProjects();
    if (user && user.userType === 'student') {
      fetchMyApplications();
    }
  }, [user]);

  // Filter projects whenever filters change
  useEffect(() => {
    applyFilters();
  }, [projects, searchText, categoryFilter, budgetFilter, levelFilter]);

  const fetchProjects = async () => {
    try {
      let res;
      if (user && user.userType === 'student') {
        try {
          res = await API.get('/match/projects');
        } catch (err) {
          res = await API.get('/project');
        }
      } else {
        res = await API.get('/project');
      }
      setProjects(res.data);
      setLoading(false);
    } catch (err) {
      console.error('Fetch error:', err);
      setLoading(false);
    }
  };

  const fetchMyApplications = async () => {
    try {
      const res = await API.get('/application/student');
      const appliedIds = res.data.map(app => app.project._id);
      setAppliedProjects(appliedIds);
    } catch (err) {
      console.error('Fetch applications error:', err);
    }
  };

  const applyFilters = () => {
    let result = [...projects];

    // Search filter
    if (searchText.trim()) {
      const lower = searchText.toLowerCase();
      result = result.filter(p =>
        p.title.toLowerCase().includes(lower) ||
        p.description.toLowerCase().includes(lower) ||
        p.requiredSkills.some(s => s.toLowerCase().includes(lower))
      );
    }

    // Category filter
    if (categoryFilter !== 'All Categories') {
      result = result.filter(p => p.category === categoryFilter);
    }

    // Budget filter
    if (budgetFilter !== 'All Budgets') {
      if (budgetFilter === '$0 - $500') result = result.filter(p => p.budget >= 0 && p.budget <= 500);
      else if (budgetFilter === '$500 - $1000') result = result.filter(p => p.budget > 500 && p.budget <= 1000);
      else if (budgetFilter === '$1000+') result = result.filter(p => p.budget > 1000);
    }

    // Experience level filter
    if (levelFilter !== 'All Levels') {
      result = result.filter(p => p.experienceLevel === levelFilter.toLowerCase());
    }

    setFilteredProjects(result);
  };

  const handleApplySuccess = () => {
    setSelectedProject(null);
    fetchMyApplications();
    alert('✅ Application submitted successfully!');
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-16 w-16 border-t-4 border-primary"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 py-12">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">

        {/* Header */}
        <div className="mb-8">
          <h1 className="text-4xl font-bold text-gray-800">Browse Projects</h1>
          <p className="text-gray-600 mt-2">
            {user && user.userType === 'student'
              ? 'Projects matched to your skills (if profile exists). Otherwise showing all projects.'
              : 'Discover exciting projects for students'}
          </p>
        </div>

        {/* Filters */}
        <div className="bg-white rounded-lg shadow-md p-6 mb-8">
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <div className="relative">
              <FiSearch className="absolute left-3 top-3 text-gray-400" />
              <input
                type="text"
                value={searchText}
                onChange={(e) => setSearchText(e.target.value)}
                placeholder="Search projects..."
                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-primary"
              />
            </div>

            <select
              value={categoryFilter}
              onChange={(e) => setCategoryFilter(e.target.value)}
              className="px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-primary"
            >
              <option>All Categories</option>
              <option>Web Development</option>
              <option>Mobile Apps</option>
              <option>UI/UX Design</option>
              <option>Data Science</option>
              <option>Content Writing</option>
              <option>Digital Marketing</option>
            </select>

            <select
              value={budgetFilter}
              onChange={(e) => setBudgetFilter(e.target.value)}
              className="px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-primary"
            >
              <option>All Budgets</option>
              <option>$0 - $500</option>
              <option>$500 - $1000</option>
              <option>$1000+</option>
            </select>

            <select
              value={levelFilter}
              onChange={(e) => setLevelFilter(e.target.value)}
              className="px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-primary"
            >
              <option>All Levels</option>
              <option>Beginner</option>
              <option>Intermediate</option>
              <option>Expert</option>
            </select>
          </div>
        </div>

        {/* Results Count */}
        <div className="mb-4">
          <p className="text-gray-600">
            Showing <span className="font-bold text-gray-800">{filteredProjects.length}</span> project{filteredProjects.length !== 1 ? 's' : ''}
          </p>
        </div>

        {/* Project Cards */}
        <div className="space-y-6">
          {filteredProjects.length === 0 ? (
            <div className="bg-white rounded-lg shadow-md p-12 text-center">
              <p className="text-gray-600 text-lg">No projects found matching your criteria.</p>
              <button
                onClick={() => {
                  setSearchText('');
                  setCategoryFilter('All Categories');
                  setBudgetFilter('All Budgets');
                  setLevelFilter('All Levels');
                }}
                className="mt-4 px-6 py-2 bg-primary text-white rounded-lg hover:bg-secondary transition"
              >
                Clear Filters
              </button>
            </div>
          ) : (
            filteredProjects.map((project) => {
              const alreadyApplied = appliedProjects.includes(project._id);

              return (
                <div key={project._id} className="bg-white rounded-lg shadow-md hover:shadow-xl transition p-6">
                  <div className="flex justify-between items-start mb-4">
                    <div className="flex-1 pr-4">
                      {/* Title + Match Score */}
                      <div className="flex items-center flex-wrap gap-3 mb-2">
                        <h2 className="text-2xl font-bold text-gray-800">{project.title}</h2>
                        {project.matchScore !== undefined && (
                          <span className={`px-3 py-1 rounded-full text-sm font-semibold ${
                            project.matchScore >= 70 ? 'bg-green-100 text-green-700' :
                            project.matchScore >= 40 ? 'bg-yellow-100 text-yellow-700' :
                            'bg-red-100 text-red-700'
                          }`}>
                            {project.matchScore}% Match
                          </span>
                        )}
                        {alreadyApplied && (
                          <span className="px-3 py-1 bg-blue-100 text-blue-700 rounded-full text-sm font-semibold">
                            ✅ Applied
                          </span>
                        )}
                      </div>

                      <p className="text-gray-600 mb-4">{project.description}</p>

                      {/* Skills */}
                      <div className="flex flex-wrap gap-2 mb-4">
                        {project.requiredSkills.map((skill, index) => (
                          <span
                            key={index}
                            className={`px-3 py-1 rounded-full text-sm font-medium ${
                              project.matchingSkills && project.matchingSkills.includes(skill)
                                ? 'bg-primary text-white'
                                : 'bg-gray-100 text-gray-700'
                            }`}
                          >
                            {skill}
                          </span>
                        ))}
                      </div>

                      {/* Meta Info */}
                      <div className="flex items-center flex-wrap gap-4 text-gray-600">
                        <div className="flex items-center space-x-2">
                          <FiDollarSign className="text-primary" />
                          <span className="font-medium">${project.budget}</span>
                        </div>
                        <div className="flex items-center space-x-2">
                          <FiClock className="text-primary" />
                          <span>{project.duration}</span>
                        </div>
                        <span className={`px-3 py-1 rounded-full text-sm font-medium ${
                          project.experienceLevel === 'beginner' ? 'bg-green-100 text-green-700' :
                          project.experienceLevel === 'intermediate' ? 'bg-yellow-100 text-yellow-700' :
                          'bg-red-100 text-red-700'
                        }`}>
                          {project.experienceLevel.charAt(0).toUpperCase() + project.experienceLevel.slice(1)}
                        </span>
                      </div>
                    </div>

                    <button className="text-gray-300 hover:text-primary transition">
                      <FiBookmark size={24} />
                    </button>
                  </div>

                  {/* Footer */}
                  <div className="flex justify-between items-center pt-4 border-t border-gray-100">
                    <div className="text-sm text-gray-500">
                      Posted by: <span className="font-medium text-gray-700">{project.client?.name || 'Client'}</span>
                    </div>

                    {user && user.userType === 'student' ? (
                      <button
                        onClick={() => !alreadyApplied && setSelectedProject(project)}
                        disabled={alreadyApplied}
                        className={`px-6 py-2 rounded-lg font-semibold transition ${
                          alreadyApplied
                            ? 'bg-gray-200 text-gray-500 cursor-not-allowed'
                            : 'bg-primary text-white hover:bg-secondary'
                        }`}
                      >
                        {alreadyApplied ? 'Already Applied' : 'Apply Now'}
                      </button>
                    ) : !user ? (
                      <Link
                        to="/register"
                        className="px-6 py-2 bg-primary text-white rounded-lg hover:bg-secondary transition font-semibold"
                      >
                        Sign up to Apply
                      </Link>
                    ) : null}
                  </div>
                </div>
              );
            })
          )}
        </div>
      </div>

      {/* Apply Modal */}
      {selectedProject && (
        <ApplyModal
          project={selectedProject}
          onClose={() => setSelectedProject(null)}
          onSuccess={handleApplySuccess}
        />
      )}
    </div>
  );
};

export default Browse;
